  str_season_maze_ore_room_tips_main = "เลือก<color=#A0690E>จำนวนรอบที่จะส่งพวกเขาออกไป</color> ยิ่งส่งพวกเขาออกไปมากเท่าไร คุณก็จะได้รับ<color=#A0690E>รางวัล</color>มากขึ้น ส่งออโรเรียนใด ๆ ก็ได้รับรางวัล",
