  str_season_maze_card_eft_des_1 = "ได้รับรองเท้าบินคู่หนึ่ง",
  str_season_maze_card_eft_des_2 = "ได้รับดอกเบี้ยความฝันจำนวนสุ่ม",
  str_season_maze_card_eft_des_3 = "คัดลอกการ์ดทำนายฝันที่เล่นในรอบก่อนหน้านี้",
  str_season_maze_card_bag_step_des_1 = "ขั้นตอนการดำเนินการ",
  str_season_maze_card_bag_resource_des_1 = "Dream Coins are the smallest units that make up dream energy, as well as the most effective currency in dreams as they can be exchanged for various items within dreams.",
  str_season_maze_card_bag_resource_des_2 = "Dream EXP นี่คือความรู้และประสบการณ์ที่คุณได้รับในฝัน เมื่อ Dream EXP ถึงมาตรฐานสำหรับการอัปเกรด ระดับฝันจะเพิ่มขึ้น ทำให้ระดับของ Aurorians และอุปกรณ์เพิ่มขึ้นและให้รางวัลทรัพยากรอื่น ๆ",
  str_season_maze_card_bag_resource_des_3 = "Cyclique. คุณต้องมี Cyclique พร้อมกับฝันเพียงพอเพื่อให้คุณสามารถเคลื่อนที่ได้ราบรื่นในฝัน หาก Cyclique ลดลงเป็น 0 การสำรวจจะสิ้นสุดโดยอัตโนมัติ แต่ละรอบการต่อสู้ใช้ 1 แต้มของ Cyclique ในกรณีที่ล้มเหลวต่อ Dream Devourer คุณยังสามารถใช้ Cyclique สำหรับการพยายามอีกครั้ง",
  str_season_maze_card_bag_resource_des_4 = "ดอกเบี้ยความฝัน ดอกเบี้ยความฝันแทนจำนวนเหรียญความฝันที่สามารถรวบรวมได้ในเหตุการณ์ความฝัน ณ ท้ายรอบแต่ละรอบ การตัดสินจะเกิดขึ้นและมอบเหรียญความฝันให้คุณเท่ากับดอกเบี้ยความฝัน",
  str_season_maze_card_bag_resource_des_5 = "Dream Orbs นั่นคือความทรงจำและความรู้สึกที่ถูกทิ้งไว้โดยผู้ฝันเดิมที่ถูกหุ้มด้วยชั้นๆ ของพลังงานฝัน หลังจากถูกเก็บขึ้นมา Dream Orbs สามารถเพิ่มพลังการต่อสู้ในฝัน ดังนั้นจงระวังอย่าปล่อยให้ Dream Devourer เก็บพวกมันขึ้นมา!",
  str_season_maze_card_bag_resource_des_6 = "จำนวนการ์ดทำนายฝันที่ได้รับในรอบถัดไป +2, สูงสุด +5",
  str_season_maze_card_bag_resource_des_7 = "รองเท้าบินเป็นไอเท็มช่วยฝันที่สร้างขึ้นจากพลังงานฝันที่สึกหรอ และอนุญาตให้ผู้ใช้เคลื่อนที่ไปข้างหน้าอีก 1 ก้าว ในรอบนี้ การกระทำของแต่ละการ์ดทำนายฝัน +1 ก้าว",
  str_season_maze_card_bag_extra_des_1 = "คัดลอกการ์ดทำนายฝันที่เล่นในรอบก่อนหน้านี้",
  str_season_maze_pet_less_one_available = "ออโรเรียนคนสุดท้ายไม่สามารถส่งออกได้",
  str_season_maze_card_giveup = "ข้ามการเลือกการ์ดทำนายฝันนี้หรือไม่",
  str_season_maze_once_item_info_title = "ไอเทมช่วยเหลือในฝัน",
  str_season_maze_once_no_select = "เลือกสนามฝันที่อันตรายเป็นเป้าหมายของระเบิดฝัน!",
  str_season_maze_item_cant_use = "คุณไม่สามารถใช้การ์ดดูดวงฝันในตอนนี้ ไอเทมช่วยฝันไม่สามารถใช้ในเวลานี้",
  str_season_maze_once_1_name = "รองเท้าบิน",
  str_season_maze_once_2_name = "เจ็ท",
  str_season_maze_once_3_name = "โล่ความปลอดภัย",
  str_season_maze_once_4_name = "ระเบิดฝัน",
  str_season_maze_once_1_desc = "หลังจากใช้ \"รองเท้าบิน\" ในรอบนี้ การ์ด \"ดวงใจในฝัน\" ทั้งหมดในมือคุณจะได้เพิ่มขั้นตอนการกระทำ +1",
  str_season_maze_once_2_desc = "หลังจากใช้ Jet จำนวนขั้นตอนการกระทำของ Caelestite ในรอบนี้จะเท่ากับผลรวมของขั้นตอนการกระทำจาก Dream Divination Cards ทั้งหมดที่ได้รับในรอบนี้ แต่ไม่สามารถรับรางวัลทรัพยากรจาก Dream Divination Cards นี้ได้",
  str_season_maze_once_3_desc = "หลังจากใช้ Safety Shield, Caelestite จะไม่เล่น Dream Divination Cards ใดๆ ในรอบนี้และจะถูกโทรพอร์ตไปยัง Safe Dream Realm ใน Safe Dream Realm นั้น สามารถเรียก Aurorians, ซื้อของ, รักษา Aurorians, ฟื้นฟู Aurorians, และฉีด Dream Coins เข้าไปใน Dream Forge ได้",
  str_season_maze_once_4_desc = "เมื่อใช้ Dream Bomb สามารถเลือก Dream Realm ที่อันตรายเพื่อนำออกโดยตรงและรางวัลสำหรับการนำออก Dream Realm จะได้รับ",
  str_season_maze_even_desc_1001 = "คุณสแกนรอบ ๆ ในความสับสน - ไม่มีศัตรู ไม่มีสมบัติ... ไม่มีอะไรเลย ผนังที่มองไม่เห็นหยุดคุณไว้ในทางของคุณด้วยเสียง \"Thump!\" ที่ดัง\n\n\"กำลังวิเคราะห์สถานการณ์... พลังงานในสามัญชนนี้แกว่งไปมาเกินไปจนไม่สามารถระบุตำแหน่งได้อย่างแม่นยำ\" หน้าของผู้กระจ่างให้สว่างกลายเป็นสีแดงร้อนจากการทำงานที่เร่งรัด \"นี่คือสามัญชนที่ไม่รู้จัก อาจารย์ฟรานซิสกล่าวว่าเขาชอบความไม่แน่นอนของสามัญชนประเภทนี้ นอกจากนี้ ภาพของผู้ฝันที่ยังคงอยู่บางครั้งจะปรากฏขึ้น\"ในคำอื่น ๆ คุณอาจพบเพื่อนเก่าของคุณที่นี่\n\n\"มีเส้นทางการออกเดินทางสามเส้นที่ถูกกำหนดไว้ กรุณาเลือก ข้อสังเกต: เส้นทางที่แตกต่างกันให้รางวัลที่แตกต่างกัน คุณแนะนำให้วางแผนสำหรับสถานการณ์ที่แย่ที่สุดเพื่อหลีกเลี่ยงประสบการณ์การเล่นที่ไม่ดี\"\n\nเหมือนกับการรับรู้ความวิตกกังวลของคุณ ผู้กระจ่างให้สว่างทันทีอธิบายว่า \"ผลที่แย่ที่สุดคือไม่ได้รับรางวัล\" นั่นดีกว่าเยอะแยะ... ใช่ไหม?",
  str_season_maze_even_desc_1002 = "\"กำลังวิเคราะห์สถานการณ์...\" ผู้กระจ่างให้สว่างกำลังมองอยู่ทั่วท้องฟ้า ดูเหมือนว่ามีเพชรใสๆหลายๆอันกำลังเคลื่อนที่อยู่ภายใน... แม้ว่าคุณจะไม่เห็นอะไร แต่คุณรู้ว่าคุณกำลังอยู่ในโลกความฝันที่ไม่รู้จักอีกครั้ง\n\n\"ได้กำหนดเส้นทางการออกเดินทางสามเส้นแล้ว โปรดเลือก\"\n\nเหมือนว่าจะส่งกำลังใจให้คุณ ผู้กระจ่างให้สว่างดึงเสื้อคุณและพูดด้วยเสียงเบาๆ \"ฉันมีความรู้สึกว่าคุณอาจจะจับ Dream Coins ได้ครั้งนี้นะ\"",
  str_season_maze_even_desc_1003 = "\"กำลังวิเคราะห์สถานการณ์...\" อาจเป็นเพราะความตื่นเต้นและความหวาดเสียวจาก \"ความไม่แน่นอน\" ที่คุณรู้สึกในสถานที่ฝันที่ไม่รู้จักก่อนหน้านี้ ทำให้คุณเริ่มรอคอยผลการคำนวณของผู้กระจ่างให้สว่าง\n\n\"สรุป: คุณมีความชอบในสถานที่ฝันที่ไม่รู้จักเหมือนกับอาจารย์ฟรานซิส\"ผู้กระจ่างให้สว่างดูพอใจกับการสรุป \"คำอธิบาย: คุณควรรู้แล้วว่าฉันไม่ได้หลอกคุณ การเล่นเกมในความฝันนั้นน่าสนใจมาก ไม่, ฉันไม่มีความรู้สึกของตัวเอง แต่ฉันสามารถสรุปความรู้สึกของผู้ท่องเที่ยวในฝันได้\"",
  str_season_maze_even_desc_1004 = "ผู้กระจ่างให้สว่างก้มลงและกวาดดินมาห handful  \"อาจารย์ฟรานซิสเคยกล่าวว่ามีสิ่งมีชีวิตที่นุ่มนวลในทะเลที่จะมัดทรายที่ซึมเข้าไปในร่างกายของมันด้วยน้ำตาที่เจ็บปวดจนกระทั่งที่สุดความเจ็บปวดนั้นกลายเป็นมุกที่สวยงาม\"\n\nผู้กระจ่างให้สว่างหยุดพัก, ดูเหมือนเด็กหญิงธรรมดาที่ชอบนิทาน \"มีสิ่งที่คล้ายคลึงกันในฝัน\"",
  str_season_maze_even_desc_1005 = "\"สรุป: ฝันร้ายแตกต่างจากฝันดี\" \n\nแน่นอนว่ามันต่างกัน คุณไม่จำเป็นต้องคิดเลยก็บอกได้ แต่สำหรับผู้กระจ่างให้สว่าง เธอต้องรวบรวมข้อมูลอย่างมากมายเพื่อสรุปความรู้เดียวกัน\n\nนี่คือความหมายของ \"เฉพาะในฝันร้ายเท่านั้นที่ความเจ็บปวดของผู้ฝันจะถูกแปลงเป็น Dream Orb\" หรือเปล่า?!\n\nคุณเริ่มสงสัยว่าผู้กระจ่างให้สว่างรู้จักความหมายของการฝันหรือไม่ และแม้กระทั่งว่าเธอมีฝันหรือไม่เลย",
  str_season_maze_even_desc_1006 = "\"ทางนี้ ทางนี้!\" \n\nคุณถูกทักทายด้วยเสียงที่ดังและชัดเจน มันมาจากอีฟ\n\nคุณมองลงไปแล้วเห็นอีฟกระโดดและสะบัดแขนขึ้น \"เฮ้ย คุณโตขึ้นมากเลยนะ? ไม่ยุติธรรมเลย ทำไมฉันถึงไม่สูงเนี่ย?\"\n\nเธอไม่ได้โกรธอะไรเลยนะ แน่นอน \"เพราะเหตุนี้ คุณสามารถเลือกของขวัญได้เพียงหนึ่งอย่างเท่านั้น!\"",
  str_season_maze_even_desc_1007 = "\"โอ้ ฉันเพิ่งสังเกตเห็นสาวน้อยที่อยู่ข้างหลังคุณ นางเป็นใคร เป็นพี่สาวของคุณหรือ?\"\n\nแม้ว่านี่จะเป็นเพียงส่วนที่เหลือของฝันของอีฟที่แท้จริง คุณก็ยังพบว่าตัวเองไม่สามารถพูดอะไรได้\n\n\"ว้าว นางน่ารักมากเลย! ทำไมคุณถึงซ่อนเธอไว้จากฉัน?\"\n\nอีฟกดแก้มของเธอไปที่ผู้กระจ่างให้สว่าง \"เราต้องไปเที่ยวด้วยกันตั้งแต่นี้เป็นต้นไป!\"",
  str_season_maze_even_desc_1008 = "\"ฮูว์ การปิกนิกก็เตรียมพร้อมแล้ว!\" \n\nอีฟยืดตัวก่อนที่จะสังเกตเห็นคุณ \"โอ้ คุณ... ทำให้ฉันตกใจเล็กน้อย...\"\n\nคุณยื่นผ้าเช็ดหน้าให้เธอเพื่อเช็ดเหงื่อที่เป็นหยดบนหน้าผาก \"ขอบคุณ! ฉันจะล้างมันก่อนที่ฉันจะคืนให้คุณ หรือว่าคุณจะเอาไปเป็นของฝาก?\"",
  str_season_maze_even_desc_1009 = "\"ขวานทองคำ, ขวานเงิน, และขวานธรรมดา แล้วของคุณคืออันไหน?\"\n\nอีฟปิดตาไว้ แต่คุณยังสังเกตเห็นเธอแอบมองคุณ คุณสั่นหัวทันที\n\n\"ดังนั้นคุณกล่าวว่าไม่มีอันใดเป็นของคุณเลยหรือ? คุณซื่อสัตย์จริง ๆ! สำหรับรางวัล คุณเลือกอันที่คุณชอบและเอาไป\"",
  str_season_maze_even_desc_1010 = "\"นี่แหละที่ฉันรอคอย มีคนมาเล่นบทบาทครอบครัวกับฉัน!\"\n\nอีฟมองคุณด้วยความสุข แต่แล้วความอายโผล่มาในสายตาของเธอ\n\n\"แต่เรามีแค่สองคน ไม่พอสำหรับบทบาททั้งหมด... ถ้ามีคนที่สามจะดีมากเลย ใช่ไหม?\"",
  str_season_maze_even_desc_1011 = "อีฟถูกเสน่ห์ดึงดูดโดยลูกประดับที่คล้ายมุกหลายลูก\n\nเมื่อเห็นคุณ เธอรีบเปลี่ยนจุดสนใจและหัวเราะเบา ๆ \"มันน่าทึ่งจริง ๆ ที่ลูกประดับสวย ๆ จะปรากฏขึ้นเมื่อฉันรู้สึกเศร้าอย่างมาก แต่ฉันก็รู้ว่าพวกเขาจริง ๆ แล้วกำลังปกป้องฉัน\"\n\nคุณไม่เคยเห็นท่าทางที่เป็นผู้ใหญ่อย่างนี้จากอีฟ \"เป็นจริงที่ความเจ็บปวดสอนคนให้เติบโต ฉันเห็นแล้ว\"",
  str_season_maze_even_desc_1012 = "เธอหยิกตาและมองคุณอย่างสงสัย \"คุณแน่ใจหรือว่าต้องการแลกสิ่งที่มีค่าที่สุดของคุณเพื่อเบี้ยนี้ในมือฉัน?\"\n\nเธอเอียงศีรษะของเธอก่อนที่จะหัวเราะเบา ๆ \"อย่าเข้าใจผิดว่ามันคือไข่มุกนะ! ถ้าจะตรงไปตรงมา อาจจะเป็น... ความเจ็บปวดของฉัน คุณยังอยากจะแลกใช่หรือไม่ ในกรณีนี้?\"เมื่อเห็นคุณพยักหน้า สีตาของเธอทันทีก็นุ่มนวลลง \"ขอบคุณที่รับความเจ็บปวดของฉัน ฉันจะไม่ยอมให้ตัวเองเศร้าอีกเลย ทุกสิ่งทุกอย่างเพื่อคุณ!\"",
  str_season_maze_even_desc_1013 = "หัวของคุณร้องเสียงหึหึ และคุณก็เห็นผู้กระจ่างให้สว่างห้า หก เจ็ด แปด เก้าคน...\n\n\"กำลังวิเคราะห์สถานการณ์...\" หน้าของผู้กระจ่างให้สว่างเบลอลง และคุณคิดว่าเสียงของเธอดูวุ่นวายและตื่นตระหนกมากกว่าปกติ \"คำเตือน, นักเดินทางในฝันต้องรักษาความสัมพันธ์ที่เพียงพอกับฝันเพื่อรักษาความเสถียร\"เมื่อคุณตื่นจากสภาวะนั้นแล้วผู้กระจ่างให้สว่างจึงอธิบายจากการทบทวนว่า \"ข้อแจ้ง: ความเสถียรของนักเดินทางในฝันก็มีผลต่อความเสถียรของผู้กระจ่างให้สว่าง หากต้องการหลีกเลี่ยงการทำงานผิดพลาดจากฝั่งของฉัน โปรดรักษาความถี่สอดคล้องกับฝัน\"",
  str_season_maze_even_desc_1014 = "\"คำถาม: คุณต้องการทราบหรือไม่ว่าทำไมอาจารย์ฟรานซิสถึงพัฒนาโมดูลสนับสนุนความฝัน?\"\n\nคุณเหยียบยินยอม และผู้กระจ่างให้สว่างปิดตาเหมือนกำลังพยายามจำ... แม้ว่าสำหรับเธอแล้ว มันเพียงแค่การจัดเรียงข้อมูลที่มีมานานแสนปี\"ตอบ: เคเลสไทต์ที่ถูกเนรเทศได้รับความทุกข์ทรมานจากความบ้าคลั่ง ในการรักษาผู้ที่ป่วย, อาจารย์ฟรานซิสเข้าไปในฝันของพวกเขาในฐานะนักเดินทางในฝัน มันเป็นอันตรายมากสำหรับนักเดินทางที่จะเคลื่อนไหวในฝันและต้องมีเครื่องมือช่วยเพื่อตรวจจับและมอนิเตอร์ความผันผวนของพลังงานอย่างถูกต้อง\"\n\n\"ด้วยความจำเป็นนั้น, อาจารย์ได้พัฒนาโมดูลสนับสนุนฝันสำหรับฉัน\"",
  str_season_maze_even_desc_1015 = "\"ตอบ: อาจารย์ฟรานซิสเชื่อว่าเพียงแค่วิทยาศาสตร์เท่านั้นที่จะช่วยชาวเคเลสไทต์ แต่เขาก็เชื่อว่ามีพลังงานลึกลับอยู่เหนือการสังเกตและความเข้าใจ...\"\n\n\"ไม่, มันไม่ใช่ศาสนาที่คุณรู้จัก พลังงานลึกลับนั้นลึกลับเพราะไม่สามารถสังเกตหรือศึกษาได้ด้วยเทคโนโลยีปัจจุบัน\"เมื่อมีการพูดถึงอาจารย์ฟรานซิส มันเสมอทำให้คุณนึกถึงเวลาที่ผู้กระจ่างให้สว่างทำความสะอาด \"แคชแห่งความเศร้า\" ของอาจารย์\n\nผู้กระจ่างให้สว่างทันทีกลายเป็นความระมัดระวัง \"กำลังวิเคราะห์สถานการณ์... ถ้าคุณต้องการให้ฉันบันทึกแคช คุณสามารถทำได้ผ่านคำสั่งเสียง.\"\n\nสิ่งนั้นทำให้คุณตกใจ... ผู้กระจ่างให้สว่างมีการติดตั้งโมดูลสื่อสารทางจิตใดๆ หรือไม่?",
  str_season_maze_even_desc_1016 = "ผู้กระจ่างให้สว่างต้องการจะพูดอะไรสักอย่างแต่ก็หยุดทันที ดูเหมือนว่าเธอมีคำถาม แต่ไม่สามารถเริ่มต้นการสอบถามได้หากไม่มีคำสั่ง\n\nหลังจากได้รับความยินยอมจากคุณ เธอจึงถามในที่สุด \"คำถาม: ฉันอยากทราบว่า โลกภายนอกนั้นเหมือนกับในฝันหรือไม่?\"\n\nเรื่องราวกลับมาที่ผู้กระจ่างให้สว่างไม่เคยออกจากหอที่เธอ \"เกิด\" คุณบอกเธอว่าโลกภายนอกกว้างขึ้น และสัญญาว่าจะพาเธอไปยังภูเขา ทะเล... ทุกที่ในโลก\"ประกาศ: จนกระทั่งเวลานั้น โปรดเน้นที่จะพัฒนาความสามารถของคุณ\" ผู้กระจ่างให้สว่างเตือนคุณอย่างเข้มงวด แม้ว่าพลุที่ระเบิดในกล่องเล็กๆ ข้างหลังของเธอจะแสดงความรู้สึกที่แท้จริงของเธอ\n\nคุณจริงๆ ได้รู้ตัวแล้วว่า ผู้กระจ่างให้สว่างไม่ใช่แค่เครื่องจักรเท่านั้น มานานแล้ว",
  str_season_maze_even_desc_1017 = "คุณอยากรู้ว่าเธอฝันอะไรไปบ้าง \n\n\"กำลังเรียกข้อมูล...\" เธอปิดตาแล้วเปิดอย่างช้า ๆ \"ขออภัย, คุณไม่ได้รับอนุญาตให้เข้าถึงไฟล์ที่เกี่ยวข้อง\" แต่ถ้าแม้แต่คุณยังไม่ได้รับอนุญาต, ใครในโลกนี้จึงได้รับอนุญาต?\"นี่คือกฎที่ผู้สร้างของฉัน อาจารย์ฟรานซิส กำหนดไว้ ท่านกล่าวว่าเพียงแค่ได้รับประสบการณ์ฝันที่เพียงพอผ่านการท่องเที่ยวในฝันเท่านั้น คนจึงจะสามารถพัฒนาความมั่นคงที่ไม่ยอมแพ้และปัญญาที่ไม่ธรรมดาในการรับมือกับฝันที่ซับซ้อนของ Caelestites โบราณ\"\n\nผู้กระจ่างให้สว่างวางมือลงบนไหล่ของคุณ \"สรุป: ฉันเชื่อว่าคุณจะสามารถเข้าถึงได้ในวันหนึ่ง\"",
  str_season_maze_even_desc_1018 = "\"กำลังค้นหาข้อมูล...\" เธอไม่เคยปิดบังอะไรในการตอบคำถามของคุณเลย แต่ครั้งนี้เธอดูเหมือนจะใช้เวลานานกว่าปกติ\n\n\"ขออภัย, ฐานข้อมูลของฉันไม่มีข้อมูลเกี่ยวกับแหล่งพลังงานของฉัน แต่คุณสามารถมั่นใจได้ว่า จากการประเมินผลการทำงานของฉัน ฉันจะไม่หมดพลังงาน อย่างน้อยไม่ในช่วงที่คุณยังมีชีวิตอยู่\"\n\nคุณไม่แน่ใจว่าควรจะกังวลหรือผ่อนคลาย ด้วยคำตอบที่คลุมเครือนนี้",
  str_season_maze_even_desc_1019 = "คุณได้รับรู้แล้วว่าความฝันนั้นคือสถานที่ที่คุณเคยเข้าไปมาก่อน แต่ตอนนี้มันมีสิ่งที่ดูเหมือนจะเป็นเครื่องมือของ Caelestite และแม้กระทั่งสภาพแวดล้อม\"ตอบ: ในฝัน การสั่นสะเทือนของพลังงานจะแตกต่างกันในแต่ละพื้นที่ เพื่อส่งเสริมการเคลื่อนที่ของ Dream Wayfarer ฉันได้ทำเครื่องหมายในพื้นที่ที่มีการสั่นสะเทือนที่เหมือนกัน แต่เนื่องจากฐานข้อมูลของฉันมีเพียงแบบจำลอง Caelestite ทุกการสั่นสะเทือนจึงถูกแปลและแสดงผลในสไตล์นั้น\"\n\nเธอหยุดพูดสักครู่ก่อนที่จะดำเนินการอย่างระมัดระวังเหมือนว่าเธอทำผิด \"คำถาม: ฉันควรเปลี่ยนการแสดงผลให้คุณหรือไม่?\"\n\nแต่สิ่งนี้ดูเหมาะสมกับคุณมาก\n\nคุณรู้สึกเหมือนอยู่บ้านจริง ๆ อย่างน้อยในที่นี้",
  str_season_maze_even_desc_1020 = "คุณรู้สึกนึกถึงหอยนาutilus ที่อยู่ใน Obelisk of Return แล้วหันมาถามผู้กระจ่างให้สว่างเกี่ยวกับมัน\n\nเธอปิดตา \"กำลังรับข้อมูล...\"\n\nคราวนี้เธอเปิดต eyes อย่างรวดเร็ว \"จากคำอธิบายของคุณ ฉันเดาว่าคุณกำลังพูดถึงหอย โดยทั่วไป Caelestite จะมีหอยหนึ่งหรือหลายเปลือก ปริมาณที่ครอบครองไม่ได้สะท้อนถึงความมั่งคั่งของ Caelestite แต่สายพันธุ์หายากถูกตามหาอย่างมาก แม้จะเกินค่าทางภายในของพวกเขาเป็นสิ่งสะสม ฉันแนะนำคุณให้ลงทุนอย่างรอบคอบ\"แม้กระสุนจะสูญเสียค่าความสำคัญในสายตาของเคเลสไทต์มานานแล้ว แต่คำแนะนำของผู้กระจ่างให้สว่างยังคงมีความเกี่ยวข้องอยู่",
  str_season_maze_even_desc_1021 = "หลังจากที่รู้ว่าไนท์เทียมคือสกุลเงินปัจจุบันของแผ่นดิน ทรงลูกบาศก์ที่อยู่ข้างๆผู้กระจ่างให้สว่างไม่แสดงอาการประหลาดใจเลย \n\nเธอคาดการณ์มันไว้แล้วหรือ?\n\n\"ตอบ: ฉันรู้ว่าสกุลเงินเป็นผลิตภัณฑ์ธรรมชาติของการพัฒนาของสังคม แต่มันไม่มีค่าสำหรับฉัน\"\n\nแล้วค่าความสำคัญสำหรับเธอคืออะไร?หน้าของเธอก็เริ่มแดงอีกครั้ง แต่คุณรู้แล้วว่าเป็นเพราะ \"สมอง\" ของเธอทำงานหนักเกินไป \"ตอบ: ฉันไม่สามารถหาคำตอบของคำถามนี้ได้ แต่จากข้อมูลในอดีต ความสนิทสนมและคำชมจากคุณคือสิ่งที่มีค่าที่สุดสำหรับฉัน\"",
  str_season_maze_even_desc_1022 = "คุณเคยเก็บสิ่งของบางอย่างในฝันที่อาจช่วยคุณสำรวจฝันในอดีต แต่พวกเขาดูเหมือนจะไม่เหมาะสมในฝันนี้...\n\n\"ตอบ: พลังงานสามารถแกว่งไปมาระหว่างฝันได้ แม้ว่าหลักการจะไม่ทราบ แต่การศึกษาแนะนำว่าฝันจริงๆแล้วมีการแลกเปลี่ยนพลังงานตามกฎบางอย่าง สิ่งของเหล่านั้นได้ตามกระแสเข้าสู่ฝันที่แตกต่างกัน คุณสามารถเอาพวกเขาไปได้เพราะพวกเขาไม่ได้เป็นของฝันใดฝันหนึ่ง\"\n\nพวกเขาอาจมาจากที่ไหน?สังเกตว่าคุณยังหลงอยู่ ผู้กระจ่างให้สว่างตอบ \"พวกเขาถูกทิ้งไว้โดยนักเดินทางแห่งฝันที่เข้ามาก่อน\"",
  str_season_maze_even_desc_1023 = "ฉันอยู่ในความฝันมานานแล้ว จะจบเมื่อไหร่นี้?\n\nเธอรู้สึกว่าคุณกำลังเหนื่อย \"คุณสามารถหยุดพักได้ การฟื้นฟูสมดุลของพลังงานในความฝันไม่ใช่งานที่สั้น โดยปกติแล้ว ความฝันมีหลายระดับ ยิ่งคนที่ฝันปิดตัวตนออกจากโลกความจริงมากขึ้น ความฝันก็จะมีระดับมากขึ้น แต่อย่างไรก็ตาม เมื่อพลังงานได้รับการสมดุลใหม่แล้ว การปรับปรุงในชีวิตจริงของพวกเขาก็จะชัดเจนขึ้น\"ผู้กระจ่างให้สว่างเคลื่อนที่ใกล้ขึ้น \"คำอธิบาย: ถ้าคุณรู้สึกเหนื่อย ฉันสามารถชงเครื่องดื่มร้อนให้คุณได้ตลอดเวลา\"",
  str_season_maze_even_desc_1024 = "เมื่อคุณดำดิ่งลึกลงไปในฝัน คุณรู้สึกว่าคุณกำลังเข้าใจกฎเกณฑ์มากขึ้นและมากขึ้น\n\n\"ประกาศ: คุณสามารถใช้ประโยชน์จากกฎและเรียกความทรงจำเกี่ยวกับออโรเรียนที่คุณรู้จักและเรียกพวกเขามาช่วยคุณ แต่โปรดทราบว่าพวกเขาจะไม่เป็นจริง และหลีกเลี่ยงการคิดว่าคุณสามารถทำอะไรก็ได้ในฝัน แม้ว่าด้วยความช่วยเหลือจากฉัน คุณไม่ควรมองข้ามอันตรายที่อาจเกิดขึ้นในฝัน\"คุณจึงสังเกตว่า ผู้กระจ่างให้สว่างพูดด้วยโทนที่แตกต่าง \"สิ่งที่กล่าวไปข้างต้นเป็นการแจ้งเตือนอัตโนมัติที่เปิดใช้งานในบางช่วงโดยโมดูลสนับสนุนความฝัน และไม่ได้สะท้อนถึงการประเมินของผู้กระจ่างให้สว่างต่อคุณ\"",
  str_season_maze_even_desc_1025 = "คุณเห็นเธอยืนหันหลังให้คุณ และลูกบาศก์ที่อยู่ข้างๆ เธอกำลังบันทึกข้อมูลบางอย่าง...\n\n\"คำเตือน, อย่าเข้าใกล้!\"\n\nเมื่อตรวจจับว่ามีใครสักคนกำลังเข้าใกล้ ผู้กระจ่างให้สว่างปล่อยเสียงเตือนที่สูงเสียด้วย แต่ก็รู้ตัวว่ามันคือคุณแล้วจึงปรับระดับเสียงกลับมาเป็นปกติ \"คำอธิบาย: สบายใจได้ ฉันจะประเมินผลการทำงานของคุณอย่างยุติธรรมและให้คะแนนที่เหมาะสม\"คุณสุดท้ายก็รู้สึกตระหนักว่าเธอได้มองดูทุกการเคลื่อนไหวของคุณและให้คะแนนคุณตลอดเวลา!\n\n\"คำอธิบาย: นี่คือคุณสมบัติเพิ่มเติมที่ฉันให้เพื่อให้คุณสามารถตรวจสอบการกระทำของคุณในฝันได้ดียิ่งขึ้น ฉันจะให้รางวัลพิเศษทุกครั้งที่คุณตรงตามเกณฑ์ที่เหมาะสม\"\n\nเอาล่ะ, ไม่สามารถดูถูกเธอได้ เพราะเธอจริงๆ แล้วเป็นครูฝึกที่ยอดเยี่ยมจริงๆ.",
  str_season_maze_even_desc_1026 = "ภายใต้คำแนะนำของเธอ คุณสังเกตเห็นว่ามีจุดเล็ก ๆ ที่สว่างวิบวับลอยอยู่ในอากาศมากมาย \n\n\"คำอธิบาย: พวกเขาคือเหรียญฝัน หน่วยที่เล็กที่สุดที่สร้างขึ้นจากพลังงานฝัน ผ่านกฎของฝัน คุณสามารถแปลงพวกเขาเป็นสิ่งที่คุณต้องการ\"\n\nเห็นว่ามันยังคงเป็นเรื่องที่ยากเกินไปสำหรับคุณ ผู้กระจ่างให้สว่างจึงใช้วิธีอื่น \"พูดง่าย ๆ เหรียญฝันคือสกุลเงินที่นี่ ในขณะที่มันดีกว่าที่จะเก็บเพิ่มเติมเท่าที่คุณสามารถ ฉันไม่แนะนำให้สะสม\"",
  str_season_maze_even_desc_1027 = "\"คำอธิบาย: Dream Devourers ที่เดินทางจะยังคงกินฝันและสร้างถ้ำบนเทือกเขาที่ถูกทำลายลง การกำจัดถ้ำเท่านั้นที่จะสามารถคืนพลังงานให้กลับสู่สมดุล\"\n\nเธอไม่เคยลืมที่จะกล่าวกฎให้คุณฟังซ้ำ ๆ อีกและอีก\n\n\"ฉันแนะนำให้สะสม Dream Coins มากพอก่อนที่จะเผชิญหน้ากับส่วนที่ลึกที่สุดของถ้ำ - Miasma\"",
  str_season_maze_even_desc_1028 = "อีฟนอนอยู่บนหญ้า โดยยกลำตัวบนขึ้น คุณเข้าใกล้แล้วเห็นว่าเธอกำลังอ่านหนังสือ\n\n\"คุณอยู่ที่นี่เหรอ ฉันกำลังอ่านหนังสือ แต่มันยากเกินไปที่ฉันจะเข้าใจ และฉันกำลังปวดหัว\" แต่ไม่นานหลังจากนั้น เธอก็กำลังคุยกับคุณเกี่ยวกับหนังสือด้วยความสนุกสนาน...\"ใช่ ฉันเข้าใจแล้วที่คุณพูดอย่างนั้น! ความยาวและความกว้างของชีวิต... นั่นคือความหมายของมัน\"\n\nแต่เธอก็ตกอยู่ในความสิ้นหวังอีกครั้ง \"แต่ถ้าฉันต้องเลือกหนึ่ง... มันเป็นการเลือกที่ยากลำบาก คุณจะเลือกอะไร?\"",
  str_season_maze_even_desc_1029 = "\"ทุกอย่างมีราคา คุณพูด... จริงหรือ?\" \n\nอีฟมองตาคุณ แต่คุณไม่รู้ว่าเธอคาดหวังคำตอบอะไร\n\n\"ราคาของ...ความรัก?\" คุณสั่นหัวและบอกอีฟว่าความรักที่แท้จริงคือความรักที่สมทบทันท่องเที่ยง\n\nคำตอบของคุณทำให้อีฟกระตือรือร้น \"ฉันเข้าใจแล้ว ดังนั้นฉันควรจะให้ความรักกลับไปที่ทุกคนเท่าที่ฉันทำได้!\"",
  str_season_maze_even_desc_1030 = "\"แฮ่ก แฮ่ก...\"\n\nแม้ว่าอีฟจะหายใจไม่ทัน แต่เธอก็ไม่เคยชะลอการวิ่งลง\n\n\"ฉ-ฉัน... ฉันโอเค... หยุดบอกฉันให้หยุด ฉันต้องฝึกฝนและออกกำลังกายเพื่อไม่ให้เป็นภาระใคร!\"\n\nเมื่อเห็นคุณยังคงยืนอยู่ อีฟหันมาและยิ้มแย้ง \"คุณทำอะไรยังคงยืนอยู่? มาสิ, อย่าบอกฉันว่าคุณแม้แต่จับฉันไม่ได้!\"",
